/*===========================================================================
 * TX/RX Descriptor Structures and Word Unions
 * (from xcand_mh_regdef.h)
 *==========================================================================*/

#ifndef BIT
#define BIT(x) (1 << (x))
#endif

#ifndef BITMASK_FROM_B_DOWNTO_A
#define BITMASK_FROM_B_DOWNTO_A(b, a) (((unsigned) -1 >> (31 - (b))) & ~((1U << (a)) - 1))
#endif


/* === TX DESCRIPTOR ========================================================= */

/* TX DESCRIPTOR Element (Word) 0 */
#if __LITTLE_ENDIAN
typedef volatile union
{
  uint32_t as_uint32;
  struct
  { /* Little Endian = start bit field with Bit 0 of the word */
    uint32_t STSu4              :  4; /*  3: 0 Status of the transmitted frame */
    uint32_t RCu5               :  5; /*  8: 4 Rolling Counter */
    uint32_t res1u2             :  2; /* 10: 9 Reserved, set to 0 */
    uint32_t res0u1             :  1; /*    11 reserved */
    uint32_t FQNu4              :  4; /* 15:12 TX FIFO Queue Number */
    uint32_t CRCu9              :  9; /* 24:16 DESC CRC */
    uint32_t ENDu1              :  1; /*    25 END */
    uint32_t PQu1               :  1; /*    26 0= TX FIFO Queue, 1= TX Priority Queue */
    uint32_t IRQu1              :  1; /*    27 Interrupt */
    uint32_t NEXTu1             :  1; /*    28 Next */
    uint32_t WRAPu1             :  1; /*    29 Wrap */
    uint32_t HDu1               :  1; /*    30 Header Descriptor of Frame */
    uint32_t VALIDu1            :  1; /*    31 Valid */
  } as_TX_FIFO_Queue;
  struct
  { /* Little Endian = start bit field with Bit 0 of the word */
    uint32_t STSu4              :  4; /*  3: 0 Status */
    uint32_t RCu5               :  5; /*  8: 4 Rolling Counter */
    uint32_t res0u2             :  2; /* 10: 9 Reserved, set to 0 */
    uint32_t PQSNu5             :  5; /* 15:11 TX Priority Queue Slot Number */
    uint32_t CRCu9              :  9; /* 24:16 DESC CRC */
    uint32_t ENDu1              :  1; /*    25 END */
    uint32_t PQu1               :  1; /*    26 0= TX FIFO Queue, 1= TX Priority Queue */
    uint32_t IRQu1              :  1; /*    27 Interrupt */
    uint32_t NEXTu1             :  1; /*    28 Next */
    uint32_t WRAPu1             :  1; /*    29 Wrap */
    uint32_t HDu1               :  1; /*    30 Header Descriptor of Frame */
    uint32_t VALIDu1            :  1; /*    31 Valid */
  } as_TX_PRIO_Queue;
} XCAND_MH_TX_DESC_ELEM0_union;
#endif

/* TX DESCRIPTOR Element (Word) 1 */
#if __LITTLE_ENDIAN
typedef volatile union
{
  uint32_t as_uint32;
  struct
  { /* Little Endian = start bit field with Bit 0 of the word */
    uint32_t res2u2             :  2; /*  1: 0 reserved */
    uint32_t NHDOu10            : 10; /* 11: 2 Next Header Descriptor Offset */
    uint32_t res1u1             :  1; /*    12 reserved */
    uint32_t INu3               :  3; /* 15:13 XCAND Instance number */
    uint32_t SIZEu10            : 10; /* 25:16 Number of valid data words in data container */
    uint32_t PLSRCu1            :  1; /*    26 Payload Source */
    uint32_t res0u5             :  5; /* 31:27 reserved */
  } as_TX_FIFO_Queue;
  struct
  { /* Little Endian = start bit field with Bit 0 of the word */
    uint32_t res2u2             :  2; /*  1: 0 reserved */
    uint32_t TDOu10             : 10; /* 11: 2 Trailing Descriptor Offset */
    uint32_t res1u1             :  1; /*    12 reserved */
    uint32_t INu3               :  3; /* 15:13 XCAND Instance number */
    uint32_t SIZEu10            : 10; /* 25:16 Number of valid data words in data container */
    uint32_t PLSRCu1            :  1; /*    26 Payload Source */
    uint32_t res0u5             :  5; /* 31:27 reserved */
  } as_TX_PRIO_Queue;
} XCAND_MH_TX_DESC_ELEM1_union;
#endif

