/* === RX FILTER Element ===================================================== */
typedef union {
  uint32_t as_uint32;
  struct{
    uint32_t CREFI0u8           :  8; /* 00..07 Comparison Reference Index 0 */
    uint32_t WI0u2              :  2; /* 08..09 Word Index 0 */
    uint32_t AR0u1              :  1; /*     10 Accept or reject on match 0 */
    uint32_t res1u1             :  1; /*     11 */
    uint32_t CREFI1u8           :  8; /* 12..19 Comparison Reference Index 1 */
    uint32_t WI1u2              :  2; /* 20..21 Word Index 1 */
    uint32_t AR1u1              :  1; /*     22 Accept or reject on match 1 */
    uint32_t res0u3             :  3; /* 23..25 */
    uint32_t BLKu1              :  1; /*     26 BlackList */
    uint32_t IRQu1              :  1; /*     27 Interrupt */
    uint32_t FIFOu4             :  4; /* 28..31 RX FIFO Queue number */
  } as_s;
} XCAND_MH_RX_FILTER_ELEMENT_UNION;


